@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @_allTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
        <span class="stat-item"><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
        <span class="stat-item"><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @_allTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" placeholder="Search tasks by title..." @bind="_searchQuery" @bind:event="oninput" class="search-input" />
    </div>

    <!-- Kanban Columns -->
    <div class="kanban-board">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            <div class="kanban-column">
                <div class="column-header">
                    <h3>@column <span class="task-count">(@tasks.Count)</span></h3>
                </div>
                <div class="column-body">
                    @foreach (var task in tasks)
                    {
                        <div class="task-card">
                            <div class="task-title">@task.Title</div>
                            <div class="task-assignee">@task.Assignee</div>
                            <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                            <div class="task-actions">
                                @if (GetColumnIndex(column) > 0)
                                {
                                    <button class="btn btn-sm btn-move" @onclick="() => MoveTask(task, -1)" disabled="@_processing">← Move Left</button>
                                }
                                @if (GetColumnIndex(column) < _columns.Length - 1)
                                {
                                    <button class="btn btn-sm btn-move" @onclick="() => MoveTask(task, 1)" disabled="@_processing">Move Right →</button>
                                }
                            </div>
                        </div>
                    }
                </div>
                @if (_showForm[column])
                {
                    <div class="add-task-form">
                        <input type="text" placeholder="Title" @bind="_formData[column].Title" class="form-input" />
                        <input type="text" placeholder="Assignee" @bind="_formData[column].Assignee" class="form-input" />
                        <select @bind="_formData[column].Priority" class="form-input">
                            <option value="High">High</option>
                            <option value="Medium">Medium</option>
                            <option value="Low">Low</option>
                        </select>
                        <input type="date" @bind="_formData[column].DueDate" class="form-input" />
                        <div class="form-actions">
                            <button class="btn btn-save" @onclick="() => SaveTask(column)" disabled="@_processing">Save</button>
                            <button class="btn btn-cancel" @onclick="() => CancelForm(column)">Cancel</button>
                        </div>
                    </div>
                }
                else
                {
                    <button class="btn btn-add" @onclick="() => ShowForm(column)">+ Add Task</button>
                }
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private bool _processing;
    private string? _error;
    private string _searchQuery = string.Empty;
    private Dictionary<string, bool> _showForm = new();
    private Dictionary<string, FormModel> _formData = new();

    private class FormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Assignee { get; set; } = string.Empty;
        public string Priority { get; set; } = "Medium";
        public DateTime DueDate { get; set; } = DateTime.Today.AddDays(7);
    }

    protected override async Task OnInitializedAsync()
    {
        foreach (var col in _columns)
        {
            _showForm[col] = false;
            _formData[col] = new FormModel();
        }

        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status) =>
        _allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrWhiteSpace(_searchQuery) ||
                        t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private int GetColumnIndex(string column) => Array.IndexOf(_columns, column);

    private async Task MoveTask(TaskItem task, int direction)
    {
        var currentIndex = GetColumnIndex(task.Status);
        var newIndex = currentIndex + direction;
        if (newIndex < 0 || newIndex >= _columns.Length) return;

        _processing = true;
        try
        {
            var newStatus = _columns[newIndex];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            _allTasks = _allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            _processing = false;
        }
    }

    private void ShowForm(string column)
    {
        _showForm[column] = true;
        _formData[column] = new FormModel();
    }

    private void CancelForm(string column)
    {
        _showForm[column] = false;
    }

    private async Task SaveTask(string column)
    {
        var form = _formData[column];
        if (string.IsNullOrWhiteSpace(form.Title)) return;

        _processing = true;
        try
        {
            var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
            // The service creates tasks; if the returned status differs from the column, update it
            if (newTask.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(newTask.Id, column);
                newTask = newTask with { Status = column };
            }
            _allTasks.Add(newTask);
            _showForm[column] = false;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            _processing = false;
        }
    }
}

